Method.Source:
    /// <summary>
    /// For charge through SO, if settlement discount exclude charges parameter is Yes
    /// recalculate the settlement discount exluding any charges for the totals screen
    /// The value will also flow into CUSTINVOICEJOUR.CASHDISC
    /// </summary>
    /// <returns>Settlement discount amount</returns>
    public DiscAmount cashDiscAmount()
    {
        totalCashDisc = next cashDiscAmount();

        METVendParameters metVendParameters = METVendParameters::find();                

        if (metVendParameters.SettlementDiscChargeExclusion
        &&  this.salesTable.METSalesOrderType == metVendParameters.SalesOrderType)
        {
            totalCashDisc = CustParameters::cashDiscAmount(
                        this.cashDiscCode(),
                        this.currencyCode(),
                        this.totalAmount() - this.totalMarkup(), // exclude charges from the amount
                        this.totalAmount() - this.totalMarkup() - this.totalTaxAmount(), // exclude charges from the amount
                        this.cashDiscPercent());
        }
        return totalCashDisc;
    }
